    subtotal = tarifa_base * multiplicadores[regiao]

    # 4. Expresso: +40%
    if expresso:
        subtotal *= 1.40

    # 5. Frete grátis (ignora o cupom, mesmo que inválido)
    if valor_pedido >= 299.90 and not expresso and regiao in ("S", "SE", "CO"):
        return 0.0

    # 6. Cupons (case-insensitive)
    if cupom:
        cupom_up = cupom.upper()
        if cupom_up == "FRETE10":
            subtotal *= 0.90
        elif cupom_up == "FRETEMETADE":
            if peso_kg <= 5:
                subtotal *= 0.50
            # peso > 5: cupom ignorado
        else:
            raise ValueError("cupom inválido")

    # 7. Frete mínimo
    if subtotal < 9.90:
        subtotal = 9.90

    # 8. Arredondamento comercial (ROUND_HALF_UP)
    resultado = Decimal(str(subtotal)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
